"""Викторина: вопросы с вариантами и категориями.

`question_id(q)` — стабильный детерминированный id (нужен для системы 'без повторов'
в БД). Не меняй формулировки вопросов после деплоя — поменяется хеш.
"""
from __future__ import annotations
import hashlib
import random


def question_id(q: dict) -> str:
    """Стабильный id вопроса = sha1(категория + текст вопроса)."""
    raw = (q.get("cat", "any") + "|" + q["q"]).encode("utf-8")
    return "core_" + hashlib.sha1(raw).hexdigest()[:16]


