def random_question(category: str = "any") -> dict:
    """Случайный вопрос (без учёта истории — для бэк-совместимости)."""
    if category == "any" or category not in CATEGORIES:
        return random.choice(QUESTIONS)
    pool = [q for q in QUESTIONS if q["cat"] == category]
    return random.choice(pool) if pool else random.choice(QUESTIONS)


def pick_unseen(category: str, seen_ids: set[str]) -> dict | None:
    """Случайный вопрос, которого нет в seen_ids. None если пул исчерпан."""
    if category == "any" or category not in CATEGORIES:
        pool = QUESTIONS
    else:
        pool = [q for q in QUESTIONS if q["cat"] == category]
    candidates = [q for q in pool if question_id(q) not in seen_ids]
    return random.choice(candidates) if candidates else None
